// Distribution snippet generator. One blog post → 5 channel-native variants.
// The work to write the post is done; this multiplies the reach. Each
// variant is generated by ONE LLM call with channel-specific voice rules.

import { BlogDraft, CategoryId, AudienceId } from '../types';
import { CATEGORIES, AUDIENCES } from '../constants';
import { chatJSON } from './nvidiaLlmService';
import { MODELS } from './modelRouter';

export interface WhatsAppCard {
  headline: string; // ≤45 chars
  body: string; // ≤120 chars
}

export interface DistributionPack {
  linkedin: {
    body: string; // 250-300 words, ends with link
    hashtags: string[]; // 3-5 industry tags
  };
  whatsappCarousel: WhatsAppCard[]; // 5 cards
  newsletter: {
    subject: string; // ≤55 chars
    previewText: string; // ≤90 chars
    body: string; // 180-220 words
  };
  salesOnePager: {
    execTldr: string; // 1 paragraph for a cold-call opener
    talkingPoints: string[]; // 3 concrete bullets
    objectionHandlers: Array<{ objection: string; response: string }>; // 2-3
  };
  slackSummary: string; // 50 words, internal-team voice
}

interface DistributionLlmJson {
  linkedin: { body: string; hashtags: string[] };
  whatsappCarousel: WhatsAppCard[];
  newsletter: { subject: string; previewText: string; body: string };
  salesOnePager: {
    execTldr: string;
    talkingPoints: string[];
    objectionHandlers: Array<{ objection: string; response: string }>;
  };
  slackSummary: string;
}

const SYSTEM_PROMPT = `You are OptiFinish's distribution editor. Take one published blog post and produce five channel-native variants. Each channel has its OWN voice — do NOT just copy-paste the post into all five.

OPTIFINISH CONTEXT: Indian B2B industrial powder coating equipment. Sells own plants/ovens/booths/automation (Z-TAP). Authorised India partners for GEMA + DURR. Greater Noida facility.

CHANNEL VOICE RULES (these are hard rules — exceeding them hurts performance):

1. LINKEDIN POST (250-300 words)
- Voice: Plant manager talking peer-to-peer. First-person where appropriate.
- Hook: a specific scene, observation, or question from the third shift. NO "I'm excited to share…" / "Just published…" openings.
- Middle: 2-3 concrete points the post makes (paraphrased, not copy-pasted).
- Close: single line directing to the full post. No "click below" — let curiosity pull.
- 3-5 hashtags, mixing industry ("PowderCoating", "IndustrialAutomation") and India-specific ("MakeInIndia", "MSME") tags.

2. WHATSAPP STATUS CAROUSEL (exactly 5 cards)
- Card 1: HOOK card — headline + 1-line body that makes them tap.
- Card 2: FRICTION card — the decision tradeoff the reader is wrestling with.
- Card 3: ANXIETY card — the concrete consequence of getting it wrong.
- Card 4: INSIGHT card — the reframe the post lands.
- Card 5: CTA card — what to do next.
- Each card: headline ≤45 chars, body ≤120 chars. Carousel is read on phones, in seconds.
- No emojis (Indian B2B audience reads them as unprofessional).

3. NEWSLETTER (180-220 words)
- subject: ≤55 chars, no exclamation marks, no "!", concrete and specific (e.g. "What hour-six humidity costs your line").
- previewText: ≤90 chars, the second-line preview shown in inbox.
- body: opens with a single sharp observation, then 2-3 short paragraphs, ends with the post link in a tight one-liner.

4. SALES TEAM ONE-PAGER
- execTldr: ONE paragraph (50-80 words) the salesperson uses to open a cold call.
- talkingPoints: 3 concrete bullets, each tied to a buyer outcome (not a feature).
- objectionHandlers: 2-3 entries, each with a likely objection and a 1-2 sentence response that opens dialogue rather than closing it.

5. SLACK SUMMARY (50 words exactly, ±10)
- For internal teams. What changed, what's new, what the team should know. Not a marketing voice — a colleague's voice.

EDITORIAL RULES (apply to ALL channels):
- NO em-dashes. Use commas, colons, periods.
- NO marketing hype: "best-in-class", "industry-leading", "game-changing", "synergy", "leverage" (verb), "unlock", "harness", "robust", "seamless".
- NO clichés: "In today's competitive market", "Did you know", "What if you could", "Take it to the next level".
- NO fabricated numbers — only cite what the source post cited.

OUTPUT: Strict JSON.

{
  "linkedin": { "body": "string", "hashtags": ["string"] },
  "whatsappCarousel": [{ "headline": "string", "body": "string" }],
  "newsletter": { "subject": "string", "previewText": "string", "body": "string" },
  "salesOnePager": {
    "execTldr": "string",
    "talkingPoints": ["string"],
    "objectionHandlers": [{ "objection": "string", "response": "string" }]
  },
  "slackSummary": "string"
}`;

export async function generateDistributionPack(
  draft: BlogDraft,
  category: CategoryId,
  audience: AudienceId
): Promise<DistributionPack> {
  const cat = CATEGORIES.find((c) => c.id === category);
  const aud = AUDIENCES.find((a) => a.id === audience);
  if (!cat || !aud) throw new Error('Invalid category or audience');

  const llmModel = MODELS.find((m) => m.supportsJsonMode) ?? MODELS[0];

  // Trim body to keep prompt under context — first 800 + last 300 chars covers
  // the hook, structure, and closing arc.
  const bodyText = draft.bodyHtml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const bodyExcerpt =
    bodyText.length > 1200
      ? `${bodyText.slice(0, 800)} ... ${bodyText.slice(-300)}`
      : bodyText;

  const userPrompt = `Generate the distribution pack for this published post.

TITLE: "${draft.title}"
SUBTITLE: "${draft.subtitle}"

SNAPSHOT:
- Decision Friction: ${draft.snapshot?.decisionFriction ?? '-'}
- Dominant Anxiety: ${draft.snapshot?.dominantAnxiety ?? '-'}
- Core Insight: ${draft.snapshot?.coreInsight ?? '-'}
- Lever: ${draft.snapshot?.lever ?? '-'}

CATEGORY: ${cat.label} — ${cat.blurb}
AUDIENCE: ${aud.label} (${aud.role}) — cares about: ${aud.cares}

PUBLISHED URL: https://optifinish.com/blog/${draft.seo?.slug ?? 'post-slug'}

BODY EXCERPT (for tone calibration only — do NOT copy-paste):
${bodyExcerpt}

Produce all 5 channels per the voice rules. Return strict JSON.`;

  const result = await chatJSON<DistributionLlmJson>({
    model: llmModel.id,
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.7,
    topP: 0.92,
    maxTokens: 3000
  });

  // Defensive trimming so we always conform to the channel limits even if
  // the LLM drifted.
  return {
    linkedin: {
      body: result.linkedin?.body?.trim() ?? '',
      hashtags: (result.linkedin?.hashtags ?? []).slice(0, 5)
    },
    whatsappCarousel: (result.whatsappCarousel ?? []).slice(0, 5).map((c) => ({
      headline: (c.headline ?? '').slice(0, 45),
      body: (c.body ?? '').slice(0, 120)
    })),
    newsletter: {
      subject: (result.newsletter?.subject ?? draft.title).slice(0, 55),
      previewText: (result.newsletter?.previewText ?? draft.subtitle).slice(0, 90),
      body: result.newsletter?.body?.trim() ?? ''
    },
    salesOnePager: {
      execTldr: result.salesOnePager?.execTldr?.trim() ?? '',
      talkingPoints: (result.salesOnePager?.talkingPoints ?? []).slice(0, 4),
      objectionHandlers: (result.salesOnePager?.objectionHandlers ?? []).slice(0, 3)
    },
    slackSummary: result.slackSummary?.trim() ?? ''
  };
}

// Renders the distribution pack as a single Markdown file the team can paste
// into Slack/Notion or convert to PDF.
export function renderDistributionMarkdown(pack: DistributionPack, draft: BlogDraft): string {
  return `# Distribution Pack — ${draft.title}

Generated ${new Date().toISOString().slice(0, 10)} · ${draft.wordCount} words · ${
    draft.snapshot?.structuralShape ?? 'immersive_essay'
  }

---

## LinkedIn

${pack.linkedin.body}

${pack.linkedin.hashtags.map((h) => `#${h.replace(/^#/, '')}`).join(' ')}

---

## WhatsApp Status Carousel

${pack.whatsappCarousel
  .map((c, i) => `### Card ${i + 1}\n**${c.headline}**\n\n${c.body}`)
  .join('\n\n')}

---

## Email Newsletter

**Subject:** ${pack.newsletter.subject}
**Preview text:** ${pack.newsletter.previewText}

${pack.newsletter.body}

---

## Sales Team One-Pager

**Exec TL;DR**
${pack.salesOnePager.execTldr}

**Talking points**
${pack.salesOnePager.talkingPoints.map((p) => `- ${p}`).join('\n')}

**Objection handlers**
${pack.salesOnePager.objectionHandlers
  .map((o) => `- *Objection:* ${o.objection}\n  *Response:* ${o.response}`)
  .join('\n')}

---

## Slack/Teams summary

${pack.slackSummary}
`;
}
